package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_1 : Integer;
    attribute accumulatedMs : Integer := 0;
    attribute stepIndex : Integer := 0;
    attribute direction : Boolean := true;
    perform action tick {
      first start;
      then assign accumulatedMs := accumulatedMs + io_1;
      then if accumulatedMs >= 2000 {
        first start;
        then assign accumulatedMs := accumulatedMs - 2000;
        then if direction {
          first start;
          then if stepIndex >= 18 {
            first start;
            then assign direction := false;
            then assign stepIndex := 17;
          }
          then if stepIndex < 18 {
            first start;
            then assign stepIndex := stepIndex + 1;
          }
        } else {
          first start;
          then if stepIndex <= 0 {
            first start;
            then assign direction := true;
            then assign stepIndex := 1;
          }
          then if stepIndex > 0 {
            first start;
            then assign stepIndex := stepIndex - 1;
          }
        }
      }
    }
    out attribute io_0 : Real = (if direction ? 5.0 * (2 * stepIndex) else 5.0 * (2 * stepIndex));
  }
  part system : Controller;
}
